sys_script_include.script:
var ChartfieldAccessUtils = Class.create();
ChartfieldAccessUtils.prototype = {
    initialize: function() {},

    getUserSysId: function(netID) {
        if (!netID) return "";
        var usr = new GlideRecord("sys_user");
        usr.addQuery("user_name", netID.trim());
        usr.query();
        if (usr.next()) return usr.sys_id.toString();
        return "";
    },

    validateRequiredFields: function(body, requiredFields) {
        for (var i = 0; i < requiredFields.length; i++) {
            if (!body[requiredFields[i]]) return requiredFields[i];
        }
        return "";
    },

    validateNestedObject: function(obj, requiredFields) {
        for (var i = 0; i < requiredFields.length; i++) {
            if (!obj[requiredFields[i]]) return requiredFields[i];
        }
        return "";
    },

    validateIRRequest: function(body) {
        var irRequiredFields = [
            'reqMasterNbr', 'foNetId', 'autoApproveAuth', 'userRequested',
            'benefeciaryNetid', 'dateRequested', 'ilearnFlag', 'brioAccess',
            'obieeAccess', 'stagingRequestsList', 'obieeRoleRequestList', 'processSeq'
        ];
        var missing = this.validateRequiredFields(body, irRequiredFields);
        if (missing) return {
            valid: false,
            message: "Value " + missing + " is required."
        };
        return {
            valid: true
        };
    },

    validateSRRequest: function(body) {
        var srRequiredFields = [
            'requestNbr', 'reqMasterNbr', 'userRequested', 'benefeciaryNetid',
            'dateUpdatedEST', 'brioAccess', 'obieeAccess', 'list', 'processSeq',
            'status', 'userUpdated', 'apprStatus'
        ];
        var missing = this.validateRequiredFields(body, srRequiredFields);
        if (missing) return {
            valid: false,
            message: "Value " + missing + " is required."
        };
        return {
            valid: true
        };
    },

    createIRRequest: function(body, irCatItemSysId) {
        try {
            var fiscalOfficerSysId = this.getUserSysId(body.foNetId);
            var beneficiarySysId = this.getUserSysId(body.benefeciaryNetid);
            var userRequestedSysId = this.getUserSysId(body.userRequested);

            if (!fiscalOfficerSysId && body.autoApproveAuth != 'Y') return {
                status: 404,
                message: "Unable to locate user: " + body.foNetId
            };
            if (!beneficiarySysId) return {
                status: 404,
                message: "Unable to locate user: " + body.benefeciaryNetid
            };
            if (!userRequestedSysId) return {
                status: 404,
                message: "Unable to locate user: " + body.userRequested
            };

            var variables = {
                reqMasterNbr: body.reqMasterNbr,
                //foNetId: body.foNetId,
                autoApproveAuth: body.autoApproveAuth,
                //beneficiaryNetid: body.benefeciaryNetid,
                beneficiaryPhone: body.benefeciaryPhone || "",
                benefeciaryDept: body.benefeciaryDept || "",
                //userRequested: body.userRequested,
                dateRequested: body.dateRequested,
                ilearnFlag: body.ilearnFlag,
				link: body.link,
                brioAccess: body.brioAccess,
                obieeAccess: body.obieeAccess,
                obieeRoleRequestList: body.obieeRoleRequestList,
                stagingRequestList: body.stagingRequestsList,
                masterApprovalhistorylist: body.masterApprovalhistorylist,
                processSeq: body.processSeq,
                fiscalOfficerRef: fiscalOfficerSysId,
                beneficiaryRef: beneficiarySysId,
                userRequestedRef: userRequestedSysId,
                requested_for: userRequestedSysId,
                onBehalfOf: "Yes"
            };
            variables.ntf_level = "";

            var masterApprovals = body.masterApprovalhistorylist;

            if (typeof masterApprovals === "string") {
                try {
                    masterApprovals = JSON.parse(masterApprovals);
                } catch (e) {
                    gs.error("Invalid masterApprovalhistorylist JSON: " + e.message);
                    masterApprovals = [];
                }
            }

            if (Array.isArray(masterApprovals) && masterApprovals.length > 0) {
                variables.ntf_level =
                    masterApprovals[masterApprovals.length - 1].ntfLevel || "";
            }

            var catalogItem = new sn_sc.CatItem(irCatItemSysId);
            var values = {
                variables: variables,
                sysparm_id: irCatItemSysId
            };
            var targetRecordDetails = catalogItem.submitProducer(values);

            return {
                status: 200,
                sl_nbr: targetRecordDetails.number || targetRecordDetails.sys_id,
                nested_errors: []
            };

        } catch (ex) {
            gs.error("Error creating IR request: " + ex.message);
            return {
                status: 500,
                message: "Unable to place IR Access Request: " + ex.message
            };
        }
    },

    createSRRequest: function(body, srCatItemSysId) {
        try {
            var fiscalOfficerSysId = this.getUserSysId(body.assignedFO);
            var userRequestedSysId = this.getUserSysId(body.userRequested);
            var beneficiarySysId = this.getUserSysId(body.benefeciaryNetid);

            if (!userRequestedSysId) return {
                status: 404,
                message: "Unable to locate user: " + body.userRequested
            };
            if (!beneficiarySysId) return {
                status: 404,
                message: "Unable to locate user: " + body.benefeciaryNetid
            };

            var date = new Date(body.dateUpdatedEST);
            var dateUpdated = new GlideDateTime();
            dateUpdated.setValue(date.getTime());

            var date1 = new Date(body.dateCreatedEST);
            var dateCreated = new GlideDateTime();
            dateCreated.setValue(date1.getTime());



            var approvalDate = "";

            if (body.autoApproveAuth == "Y") {
                approvalDate = new GlideDateTime().getDisplayValue();
            }

			var ntfLevel = "";
if (Array.isArray(body.approvalhistorylist) && body.approvalhistorylist.length > 0)
    ntfLevel = body.approvalhistorylist[0].ntfLevel || "";

            var variables = {
                requestNum: body.requestNbr,
                reqMasterNbr: body.reqMasterNbr,
                brioAccess: body.brioAccess,
                obieeAccess: body.obieeAccess,
                list: JSON.stringify(body.list),
                processSeq: body.processSeq,
                status: body.status,
                userUpdated: body.userUpdated,
                apprStatus: body.apprStatus,
                dateUpdated: dateUpdated.getDisplayValue(),
                dateCreated: dateCreated.getDisplayValue(),
                approverNetID: fiscalOfficerSysId || "",
                netID: userRequestedSysId,
                requested_for: userRequestedSysId,
                beneficiary: beneficiarySysId,
                reportingToolAccess: body.reportingToolAcess || "N",
                ntfLevel: ntfLevel,
                summary: body.summary || "",
                detail: body.requestDetail || "",
                autoApproveAuth: body.autoApproveAuth || "N",
                ilearnFlag: body.ilearnFlag || "N",
                approvalDate: approvalDate


            };

            var catalogItem = new sn_sc.CatItem(srCatItemSysId);
            var values = {
                variables: variables,
                sysparm_id: srCatItemSysId
            };
            var targetRecordDetails = catalogItem.submitProducer(values);

            return {
                status: 200,
                sl_nbr: targetRecordDetails.number || targetRecordDetails.sys_id
            };

        } catch (ex) {
            gs.error("Error creating SR request: " + ex.message);
            return {
                status: 500,
                message: "Unable to place SR Access Request: " + ex.message
            };
        }
    },

    type: 'ChartfieldAccessUtils'
};
